   160	        /* Verify this is an uncompressed bmp */
   161	    bmpfh = (BMP_FH *)cdata;
   162	    bftype = bmpfh->bfType[0] + ((l_int32)bmpfh->bfType[1] << 8);
   163	    if (bftype != BMP_ID)
   164	        return (PIX *)ERROR_PTR("not bmf format", procName, NULL);
   165	#if defined(__GNUC__)
   166	    bmph = (BMP_HEADER *)bmpfh;
   167	#else
   168	    bmpih = (BMP_IH *)(cdata + BMP_FHBYTES);
   169	#endif
   170	    compression = convertOnBigEnd32(bmpih->biCompression);
   171	    if (compression != 0)
   172	        return (PIX *)ERROR_PTR("cannot read compressed BMP files",
   173	                                procName, NULL);
