   175	        /* Find the offset from the beginning of the file to the image data */
   176	    offset = bmpfh->bfOffBits[0];
   177	    offset += (l_int32)bmpfh->bfOffBits[1] << 8;
   178	    offset += (l_int32)bmpfh->bfOffBits[2] << 16;
   179	    offset += (l_uint32)bmpfh->bfOffBits[3] << 24;
   180	
   181	        /* Read the remaining useful data in the infoheader.
   182	         * Note that the first 4 bytes give the infoheader size. */
   183	    ihbytes = convertOnBigEnd32(*(l_uint32 *)(bmpih));
   184	    width = convertOnBigEnd32(bmpih->biWidth);
   185	    height = convertOnBigEnd32(bmpih->biHeight);
   186	    depth = convertOnBigEnd16(bmpih->biBitCount);
   187	    imagebytes = convertOnBigEnd32(bmpih->biSizeImage);
