   262	    pixSetInputFormat(pix, IFF_BMP);
   263	    pixWpl = pixGetWpl(pix);
   264	    pixBpl = 4 * pixWpl;
   265	
   266	        /* Convert the bmp colormap to a pixcmap */
   267	    cmap = NULL;
   268	    if (cmapEntries > 0) {  /* import the colormap to the pix cmap */
   269	        cmap = pixcmapCreate(L_MIN(d, 8));
   270	        LEPT_FREE(cmap->array);  /* remove generated cmap array */
   271	        cmap->array  = (void *)cmapBuf;  /* and replace */
   272	        cmap->n = L_MIN(cmapEntries, 256);
   273	        for (i = 0; i < cmap->n; i++)   /* set all colors opaque */
   274	            pixcmapSetAlpha (cmap, i, 255);
   275	    }
   276	    pixSetColormap(pix, cmap);
   277	
   278	        /* Acquire the image data.  Image origin for bmp is at lower right. */
   279	    fdata = (l_uint8 *)cdata + offset;  /* start of the bmp image data */
   280	    pixdata = pixGetData(pix);
