   282	        data = (l_uint8 *)pixdata + pixBpl * (height - 1);
   283	        for (i = 0; i < height; i++) {
   284	            memcpy(data, fdata, fdatabpl);
   285	            fdata += fdatabpl;
   286	            data -= pixBpl;
   287	        }
   288	    } else {  /*  24 bpp file; 32 bpp pix
   289	             *  Note: for bmp files, pel[0] is blue, pel[1] is green,
   290	             *  and pel[2] is red.  This is opposite to the storage
   291	             *  in the pix, which puts the red pixel in the 0 byte,
   292	             *  the green in the 1 byte and the blue in the 2 byte.
   293	             *  Note also that all words are endian flipped after
   294	             *  assignment on L_LITTLE_ENDIAN platforms.
   295	             *
   296	             *  We can then make these assignments for little endians:
   297	             *      SET_DATA_BYTE(pword, 1, pel[0]);      blue
   298	             *      SET_DATA_BYTE(pword, 2, pel[1]);      green
   299	             *      SET_DATA_BYTE(pword, 3, pel[2]);      red
   300	             *  This looks like:
   301	             *          3  (R)     2  (G)        1  (B)        0
   302	             *      |-----------|------------|-----------|-----------|
   303	             *  and after byte flipping:
   304	             *           3          2  (B)     1  (G)        0  (R)
   305	             *      |-----------|------------|-----------|-----------|
   306	             *
   307	             *  For big endians we set:
   308	             *      SET_DATA_BYTE(pword, 2, pel[0]);      blue
   309	             *      SET_DATA_BYTE(pword, 1, pel[1]);      green
   310	             *      SET_DATA_BYTE(pword, 0, pel[2]);      red
   311	             *  This looks like:
   312	             *          0  (R)     1  (G)        2  (B)        3
   313	             *      |-----------|------------|-----------|-----------|
   314	             *  so in both cases we get the correct assignment in the PIX.
   315	             *
   316	             *  Can we do a platform-independent assignment?
   317	             *  Yes, set the bytes without using macros:
   318	             *      *((l_uint8 *)pword) = pel[2];           red
   319	             *      *((l_uint8 *)pword + 1) = pel[1];       green
   320	             *      *((l_uint8 *)pword + 2) = pel[0];       blue
   321	             *  For little endians, before flipping, this looks again like:
   322	             *          3  (R)     2  (G)        1  (B)        0
   323	             *      |-----------|------------|-----------|-----------|
   324	             */
   325	        extrabytes = fdatabpl - 3 * width;
   326	        line = pixdata + pixWpl * (height - 1);
   327	        for (i = 0; i < height; i++) {
   328	            for (j = 0; j < width; j++) {
   329	                pword = line + j;
   330	                memcpy(&pel, fdata, 3);
   331	                fdata += 3;
   332	                *((l_uint8 *)pword + COLOR_RED) = pel[2];
   333	                *((l_uint8 *)pword + COLOR_GREEN) = pel[1];
   334	                *((l_uint8 *)pword + COLOR_BLUE) = pel[0];
   335	                    /* should not use alpha byte, but for buggy readers,
   336	                     * set it to opaque  */
   337	                *((l_uint8 *)pword + L_ALPHA_CHANNEL) = 255;
   338	            }
   339	            if (extrabytes) {
   340	                for (k = 0; k < extrabytes; k++) {
   341	                    memcpy(&pel, fdata, 1);
   342	                    fdata++;
   343	                }
   344	            }
   345	            line -= pixWpl;
   346	        }
   347	    }
   348	
   349	    pixEndianByteSwap(pix);
   350	    if (height_neg)
   351	        pixFlipTB(pix, pix);
   352	
   353	        /* ----------------------------------------------
   354	         * The bmp colormap determines the values of black
   355	         * and white pixels for binary in the following way:
   356	         * (a) white = 0 [255], black = 1 [0]
